mapper.sql:
WHERE 1 = 1

    AND l.admin_id = #{adminId}


    AND l.action = #{action}


    AND l.target = #{target}


    AND (
        l.action LIKE CONCAT('%', #{keyword}, '%')
        OR l.target LIKE CONCAT('%', #{keyword}, '%')
        OR l.detail LIKE CONCAT('%', #{keyword}, '%')
        OR l.ip LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(au.account, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(au.name, '') LIKE CONCAT('%', #{keyword}, '%')
    )

WHERE 1 = 1
AND t.region = #{region}
AND t.biz_type = #{bizType}
AND 1 = 0
AND t.biz_type IN
#{allowedBizType}
AND t.status = #{status}
AND 1 = 0
AND t.biz_type IN
#{threshold.bizType}
AND t.created_at <= TIMESTAMPADD(MINUTE, 0 - CAST((CASE t.biz_type
WHEN #{threshold.bizType} THEN #{threshold.slaMinutes}
END) AS SIGNED), CURRENT_TIMESTAMP)
AND (t.claimed_by_admin_id IS NULL OR t.claim_expires_at IS NULL OR t.claim_expires_at <= CURRENT_TIMESTAMP)
AND t.claimed_by_admin_id = #{currentAdminId} AND t.claim_expires_at > CURRENT_TIMESTAMP
AND t.claimed_by_admin_id IS NOT NULL AND t.claimed_by_admin_id <> #{currentAdminId} AND t.claim_expires_at > CURRENT_TIMESTAMP
AND ( CAST(t.biz_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(m.company_name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sm.company_name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(ram.company_name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(mvm.company_name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(s.name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sc.name, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(d.title, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sc.summary, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(mv.reason, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(p.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(r.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(au.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(bau.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(ba.account, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(rc.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(pc.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sq.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sa.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(msg.content, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(mau.nickname, '') LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT t.biz_type, COUNT(1) AS overdue_count FROM audit_task t WHERE t.region = #{region} AND t.status = 0 AND t.biz_type IN
#{allowedBizType}
AND t.created_at <= TIMESTAMPADD(MINUTE, 0 - CAST((CASE t.biz_type
WHEN #{threshold.bizType} THEN #{threshold.slaMinutes}
END) AS SIGNED), CURRENT_TIMESTAMP) GROUP BY t.biz_type

